var PLAYERS_POOL = Object.entries(DATA).flatMap(([club, list]) => {
	return list.map(([name, rating], idx) => ({
		id: 0,
		n: name,
		c: club,
		lg: CLUB_TO_LEAGUE[club] || "Diğer Takımlar",
		r: rating,
		pos: POS_CODE_MAP[(PS[club] || "")[idx] || "M"] || "MID",
		price: 0
	}));
}).map((p, globalIdx) => ({
	...p,
	id: globalIdx,
	price: calcBasePriceWithVariance(p.n, p.r, globalIdx)
}));
var PLAYERS_BY_ID = Object.fromEntries(PLAYERS_POOL.map((p) => [p.id, p]));
